1	//! Harness integration: sends a compiled prompt to a local coding harness as a
2	//! one-off run (`claude -p`) in the project directory, streaming what it does
3	//! as it does it.
4	
5	use std::io::{BufRead as _, BufReader, Write as _};
6	use std::path::{Path, PathBuf};
7	use std::process::{Command, Stdio};
8	
9	use anyhow::{Context as _, Result, bail};
10	use futures::channel::mpsc;
11	use serde_json::Value;
12	
13	use crate::harness_mentions;
14	
15	const HARNESS_COMMAND: &str = "claude";
16	
17	/// Something the harness did, in the order it happened.
18	#[derive(Debug, PartialEq)]
19	pub enum HarnessEvent {
20	    /// A raw line of the harness's output, sent before the events parsed
21	    /// from it.
22	    Output(String),
23	    /// A new block of reply text began.
24	    TextStarted,
25	    TextDelta(String),
26	    ToolStarted {
27	        id: String,
28	        name: String,
29	    },
30	    /// A tool call's input is known; `summary` is its most telling argument.
31	    ToolInput {
32	        id: String,
33	        summary: String,
34	    },
35	    ToolFinished {
36	        id: String,
37	        is_error: bool,
38	    },
39	    Finished {
40	        is_error: bool,
41	        result: String,
42	    },
43	    Failed(String),
44	}
45	
46	/// Runs the harness once with `prompt`, and `system_prompt` appended to its
47	/// own system prompt, streaming its events. The run is stopped once the
48	/// receiver is dropped.
49	pub fn send(
50	    prompt: String,
51	    system_prompt: Option<String>,
52	    project_dir: PathBuf,
53	) -> mpsc::UnboundedReceiver<HarnessEvent> {
54	    let (tx, rx) = mpsc::unbounded();
55	    std::thread::spawn(move || {
56	        if let Err(err) = run(&prompt, system_prompt.as_deref(), &project_dir, &tx) {
57	            tx.unbounded_send(HarnessEvent::Failed(format!("{err:#}")))
58	                .ok();
59	        }
60	    });
61	    rx
62	}
63	
64	fn run(
65	    prompt: &str,
66	    system_prompt: Option<&str>,
67	    project_dir: &Path,
68	    tx: &mpsc::UnboundedSender<HarnessEvent>,
69	) -> Result<()> {
70	    let mut command = Command::new(HARNESS_COMMAND);
71	    command.args([
72	        "-p",
73	        // The spec: the harness always runs in auto mode.
74	        "--permission-mode",
75	        "auto",
76	        "--output-format",
77	        "stream-json",
78	        "--verbose",
79	        "--include-partial-messages",
80	    ]);
81	    if let Some(system_prompt) = system_prompt {
82	        command.args(["--append-system-prompt", system_prompt]);
83	    }
84	    let mut child = command
85	        .current_dir(project_dir)
86	        .stdin(Stdio::piped())
87	        .stdout(Stdio::piped())
88	        .stderr(Stdio::piped())
89	        .spawn()
90	        .with_context(|| format!("could not run `{HARNESS_COMMAND} -p`"))?;
91	
92	    // The prompt goes over stdin so its length and leading characters never
93	    // collide with command-line parsing; dropping stdin ends it.
94	    child
95	        .stdin
96	        .take()
97	        .context("the harness has no stdin")?
98	        .write_all(prompt.as_bytes())?;
99	    let stdout = child.stdout.take().context("the harness has no stdout")?;
100	    let stderr = child.stderr.take().context("the harness has no stderr")?;
101	    // Error output reaches the raw stream as it arrives, and is kept for the
102	    // error message should the run end without a result.
103	    let stderr = std::thread::spawn({
104	        let tx = tx.clone();
105	        move || {
106	            let mut text = String::new();
107	            for line in BufReader::new(stderr).lines() {
108	                let Ok(line) = line else { break };
109	                tx.unbounded_send(HarnessEvent::Output(line.clone())).ok();
110	                text.push_str(&line);
111	                text.push('\n');
112	            }
113	            text
114	        }
115	    });
116	
117	    let mut finished = false;
118	    for line in BufReader::new(stdout).lines() {
119	        let line = line?;
120	        if line.trim().is_empty() {
121	            // Nothing to parse, but the raw stream shows lines as they arrived.
122	            if tx.unbounded_send(HarnessEvent::Output(line)).is_err() {
123	                child.kill().ok();
124	                child.wait().ok();
125	                return Ok(());
126	            }
127	            continue;
128	        }
129	        let events = match serde_json::from_str::<Value>(&line) {
130	            Ok(event) => {
131	                // The skills and agents this run has are offered as mentions.
132	                harness_mentions::remember(&event, project_dir);
133	                parse(&event)
134	            }
135	            Err(_) => Vec::new(),
136	        };
137	        for event in std::iter::once(HarnessEvent::Output(line)).chain(events) {
138	            finished |= matches!(event, HarnessEvent::Finished { .. });
139	            if tx.unbounded_send(event).is_err() {
140	                child.kill().ok();
141	                child.wait().ok();
142	                return Ok(());
143	            }
144	        }
145	    }
146	
147	    let status = child.wait()?;
148	    let stderr = stderr.join().unwrap_or_default();
149	    if !finished {
150	        let stderr = stderr.trim();
151	        if stderr.is_empty() {
152	            bail!("`{HARNESS_COMMAND} -p` exited with {status}");
153	        }
154	        bail!("{stderr}");
155	    }
156	    Ok(())
157	}
158	
159	/// Translates one line of `stream-json` output. Events from subagents (those
160	/// with a `parent_tool_use_id`) are left out so the reply reads as one thread.
161	pub fn parse(event: &Value) -> Vec<HarnessEvent> {
162	    if event
163	        .get("parent_tool_use_id")
164	        .is_some_and(|parent| !parent.is_null())
165	    {
166	        return Vec::new();
167	    }
168	
169	    match str_at(event, "/type").as_deref() {
170	        Some("stream_event") => {
171	            let inner = &event["event"];
172	            match str_at(inner, "/type").as_deref() {
173	                Some("content_block_start") => {
174	                    match str_at(inner, "/content_block/type").as_deref() {
175	                        Some("text") => vec![HarnessEvent::TextStarted],
176	                        Some("tool_use") => match (
177	                            str_at(inner, "/content_block/id"),
178	                            str_at(inner, "/content_block/name"),
179	                        ) {
180	                            (Some(id), Some(name)) => vec![HarnessEvent::ToolStarted { id, name }],
181	                            _ => Vec::new(),
182	                        },
183	                        _ => Vec::new(),
184	                    }
185	                }
186	                Some("content_block_delta")
187	                    if str_at(inner, "/delta/type").as_deref() == Some("text_delta") =>
188	                {
189	                    str_at(inner, "/delta/text")
190	                        .map(HarnessEvent::TextDelta)
191	                        .into_iter()
192	                        .collect()
193	                }
194	                _ => Vec::new(),
195	            }
196	        }
197	        Some("assistant") => content_blocks(event, "tool_use")
198	            .filter_map(|block| {
199	                Some(HarnessEvent::ToolInput {
200	                    id: str_at(block, "/id")?,
201	                    summary: summarize(block.get("input")?)?,
202	                })
203	            })
204	            .collect(),
205	        Some("user") => content_blocks(event, "tool_result")
206	            .filter_map(|block| {
207	                Some(HarnessEvent::ToolFinished {
208	                    id: str_at(block, "/tool_use_id")?,
209	                    is_error: block
210	                        .get("is_error")
211	                        .and_then(Value::as_bool)
212	                        .unwrap_or(false),
213	                })
214	            })
215	            .collect(),
216	        Some("result") => vec![HarnessEvent::Finished {
217	            is_error: event
218	                .get("is_error")
219	                .and_then(Value::as_bool)
220	                .unwrap_or(false),
221	            result: str_at(event, "/result").unwrap_or_default(),
222	        }],
223	        _ => Vec::new(),
224	    }
225	}
226	
227	fn str_at(value: &Value, pointer: &str) -> Option<String> {
228	    value.pointer(pointer)?.as_str().map(str::to_string)
229	}
230	
231	fn content_blocks<'a>(event: &'a Value, kind: &'a str) -> impl Iterator<Item = &'a Value> {
232	    event
233	        .pointer("/message/content")
234	        .and_then(Value::as_array)
235	        .into_iter()
236	        .flatten()
237	        .filter(move |block| block.get("type").and_then(Value::as_str) == Some(kind))
238	}
239	
240	/// The most telling argument of a tool call: a command whole, as it is laid
241	/// out across lines where it is shown, anything else on one line.
242	fn summarize(input: &Value) -> Option<String> {
243	    const KEYS: [&str; 7] = [
244	        "command",
